try {
  TRIDENT_GNN = JSON.parse(fs.readFileSync('./trident-gnn-complete.json', 'utf8'));
  MORPH_KERNEL_ENTRY = JSON.parse(fs.readFileSync('./morph-kernel-entry-v4.json', 'utf8'));
