// ============================================
// PERSISTENCE LAYER
// ============================================
class MorphPersistence {
  constructor(config) {
    this.config = config;
    this.artifactsPath = config.persistence.artifacts_path;
    this.contractsPath = config.persistence.contracts_path;
    this.evolutionPath = config.persistence.evolution_log_path;
    this.memoryDir = path.dirname(this.artifactsPath);

    // Ensure memory directory exists
    if (!fs.existsSync(this.memoryDir)) {
      fs.mkdirSync(this.memoryDir, { recursive: true });
    }

    this.artifacts = this.load(this.artifactsPath, {});
    this.contracts = this.load(this.contractsPath, {});
    this.evolutionLog = this.load(this.evolutionPath, []);
    this.dirty = false;

    // Auto-save
    if (config.persistence.auto_save) {
      setInterval(() => this.save(), config.persistence.save_interval_ms);
    }
  }

  load(filepath, defaultValue) {
    try {
      if (fs.existsSync(filepath)) {
        return JSON.parse(fs.readFileSync(filepath, 'utf8'));
      }
    } catch (e) {
      console.warn(`[PERSISTENCE] Could not load ${filepath}: ${e.message}`);
    }
    return defaultValue;
  }

  save() {
    if (!this.dirty) return;
    try {
      fs.writeFileSync(this.artifactsPath, JSON.stringify(this.artifacts, null, 2));
      fs.writeFileSync(this.contractsPath, JSON.stringify(this.contracts, null, 2));
      fs.writeFileSync(this.evolutionPath, JSON.stringify(this.evolutionLog, null, 2));
      this.dirty = false;
      console.log('[PERSISTENCE] State saved to disk');
    } catch (e) {
      console.error(`[PERSISTENCE] Save failed: ${e.message}`);
    }
  }

  storeArtifact(id, artifact) {
    this.artifacts[id] = artifact;
    this.dirty = true;
  }

  getArtifact(id) {
    return this.artifacts[id] || null;
  }

  storeContract(id, contract) {
    this.contracts[id] = contract;
    this.dirty = true;
  }

  getContract(id) {
    return this.contracts[id] || null;
  }

  logEvolution(entry) {
    entry.timestamp = Date.now();
    this.evolutionLog.push(entry);
    this.dirty = true;
  }

  getEvolutionLog() {
    return this.evolutionLog;
  }

  listArtifacts() {
    return Object.keys(this.artifacts);
  }

  flush() {
    this.save();
  }
}

