// ============================================
// 1. INGESTION ENGINE (Mouth)
// ============================================
class MorphIngestion {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.parsers = {
      'js': new JSParser(),
      'py': new PythonParser(),
      'yaml': new YAMLParser(),
      'json': new JSONParser(),
      'html': new HTMLParser(),
      'css': new CSSParser()
    };
  }

  ingest(code, metadata = {}) {
    console.log(`[INGESTION] Ingesting ${metadata.type || 'unknown'} artifact: ${metadata.name || 'unnamed'}`);

    const parser = this.parsers[metadata.type] || this.parsers['js'];
    const ast = parser.parse(code);
    const cpg = this.buildCPG(ast, code);
    const contract = this.extractContract(cpg, code);

    const artifactId = `artifact_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const artifact = {
      id: artifactId,
      code,
      ast,
      cpg,
      contract,
      metadata,
      timestamp: Date.now(),
      size: code.length
    };

    this.orchestrator.persistence.storeArtifact(artifactId, artifact);
    this.orchestrator.gnn.ingestArtifact(artifact);

    console.log(`[INGESTION] ✅ Artifact ${artifactId} stored (${code.length} chars)`);
    return artifactId;
  }

  ingestFile(filepath) {
    const code = fs.readFileSync(filepath, 'utf8');
    const ext = path.extname(filepath).slice(1);
    const name = path.basename(filepath);
    return this.ingest(code, { type: ext, name, path: filepath });
  }

  buildCPG(ast, code) {
    return {
      nodes: this.extractNodes(ast),
      edges: this.extractEdges(ast),
      dataFlow: this.extractDataFlow(ast, code),
      controlFlow: this.extractControlFlow(ast, code),
      complexity: this.calculateComplexity(code)
    };
  }

  extractNodes(ast) {
    return ast.nodes || [];
  }

  extractEdges(ast) {
    return ast.edges || [];
  }

  extractDataFlow(ast, code) {
    const assignments = (code.match(/\b(let|const|var)\s+\w+\s*=/g) || []).length;
    const mutations = (code.match(/\w+\s*=\s*[^=]/g) || []).length;
    return { assignments, mutations, dataSources: [] };
  }

  extractControlFlow(ast, code) {
    const conditionals = (code.match(/\b(if|else|switch|case)\b/g) || []).length;
    const loops = (code.match(/\b(for|while|do)\b/g) || []).length;
    const returns = (code.match(/\breturn\b/g) || []).length;
    return { conditionals, loops, returns };
  }

  calculateComplexity(code) {
    const lines = code.split('\n').length;
    const functions = (code.match(/\bfunction\b/g) || []).length;
    const classes = (code.match(/\bclass\b/g) || []).length;
    const branches = (code.match(/\b(if|else|switch|case|for|while)\b/g) || []).length;
    return { lines, functions, classes, branches, cyclomatic: branches + 1 };
  }

  extractContract(cpg, code) {
    return {
      intent: this.inferIntent(code),
      functions: this.extractFunctions(code),
      dependencies: this.extractDependencies(code),
      interfaces: this.extractInterfaces(code),
      patterns: this.recognizePatterns(code),
      complexity: cpg.complexity
    };
  }

  inferIntent(code) {
    const intents = [];
    if (code.includes('class')) intents.push('object_oriented');
    if (code.includes('function')) intents.push('functional');
    if (code.includes('async') || code.includes('await')) intents.push('async');
    if (code.includes('import') || code.includes('require')) intents.push('modular');
    if (code.includes('export')) intents.push('library');
    if (code.includes('console.log')) intents.push('debug');
    if (code.includes('fetch') || code.includes('http')) intents.push('network');
    if (code.includes('document') || code.includes('window')) intents.push('browser');
    if (code.includes('process') || code.includes('fs.')) intents.push('node');
    return intents.length > 0 ? intents.join(', ') : 'general';
  }

  extractFunctions(code) {
    const funcs = [];
    const funcRegex = /(?:function\s+(\w+)|(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?(?:function|\([^)]*\)\s*=>))/g;
    let match;
    while ((match = funcRegex.exec(code)) !== null) {
      funcs.push(match[1] || match[2]);
    }
    return funcs;
  }

  extractDependencies(code) {
    const deps = [];
    const importRegex = /(?:import\s+.*?\s+from\s+['"]([^'"]+)['"]|require\s*\(\s*['"]([^'"]+)['"]\s*\))/g;
    let match;
    while ((match = importRegex.exec(code)) !== null) {
      deps.push(match[1] || match[2]);
    }
    return deps;
  }

  extractInterfaces(code) {
    const interfaces = [];
    if (code.includes('module.exports')) interfaces.push('commonjs');
    if (code.includes('export default')) interfaces.push('esm_default');
    if (code.includes('export {')) interfaces.push('esm_named');
    if (code.includes('export class')) interfaces.push('esm_class');
    return interfaces;
  }

  recognizePatterns(code) {
    const patterns = [];
    if (code.includes('new Event') || code.includes('addEventListener') || /on\w+\s*=/.test(code)) patterns.push('observer');
    if (code.includes('new ') && code.includes('create')) patterns.push('factory');
    if (code.includes('getInstance') || /if\s*\(!?\w+\)/.test(code)) patterns.push('singleton');
    if (code.includes('class') && code.includes('extends')) patterns.push('inheritance');
    if (code.includes('Promise') || code.includes('async')) patterns.push('async_pattern');
    if (code.includes('try') && code.includes('catch')) patterns.push('error_handling');
    return patterns;
  }
}

