// 3. UNDERSTANDING LAYER (Brain)
// ============================================
class MorphUnderstanding {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
  }

  buildRepresentation(artifactId) {
    console.log(`[UNDERSTANDING] Building representation for ${artifactId}`);

    const artifact = this.orchestrator.persistence.getArtifact(artifactId);
    if (!artifact) throw new Error(`Artifact ${artifactId} not found`);

    // We need to run study first if not already done
    let analysis = this.orchestrator.study.analyze(artifactId);

    const embedding = this.createEmbedding(artifact, analysis);
    const intent = this.extractIntent(artifact.contract);
    const capabilities = this.mapCapabilities(artifact.contract);
    const formalContract = this.formalizeContract({
      intent,
      capabilities,
      patterns: analysis.patterns,
      resonance: analysis.resonance,
      issues: analysis.issues
    });

    const representation = {
      artifactId,
      embedding,
      intent,
      capabilities,
      contract: formalContract,
      confidence: this.calculateConfidence(analysis),
      timestamp: Date.now()
    };

    this.orchestrator.persistence.storeContract(artifactId, formalContract);
    this.orchestrator.gnn.storeRepresentation(representation);

    console.log(`[UNDERSTANDING] ✅ Representation built for ${artifactId}`);
    console.log(`[UNDERSTANDING]    Intent: ${intent.primary}`);
    console.log(`[UNDERSTANDING]    Confidence: ${representation.confidence.toFixed(2)}%`);

    return representation;
  }

  createEmbedding(artifact, analysis) {
    return {
      vector: [artifact.cpg.complexity.lines, artifact.cpg.complexity.functions, artifact.cpg.complexity.cyclomatic],
      center: analysis.resonance.primaryGate % 9,
      hexagram: analysis.resonance.primaryGate,
      dimensions: {
        lines: artifact.cpg.complexity.lines,
        functions: artifact.cpg.complexity.functions,
        classes: artifact.cpg.complexity.classes,
        branches: artifact.cpg.complexity.branches
      }
    };
  }

  extractIntent(contract) {
    return {
      primary: contract.intent,
      secondary: contract.patterns.join(', ') || 'none',
      implicit: contract.dependencies.length > 0 ? 'modular' : 'standalone'
    };
  }

  mapCapabilities(contract) {
    return {
      canCreate: contract.complexity.functions > 0,
      canRead: contract.intent.includes('node') || contract.intent.includes('network'),
      canUpdate: contract.patterns.includes('observer') || contract.patterns.includes('factory'),
      canDelete: contract.patterns.includes('error_handling'),
      canTransform: contract.patterns.includes('async_pattern'),
      canIntegrate: contract.interfaces.length > 0
    };
  }

  formalizeContract({ intent, capabilities, patterns, resonance, issues }) {
    return {
      type: 'morph_contract',
      version: '1.0',
      intent,
      capabilities,
      patterns,
      resonance,
      issues,
      requirements: this.inferRequirements(intent, capabilities),
      constraints: this.inferConstraints(patterns, resonance),
      improvements: this.suggestImprovements(issues)
    };
  }

  inferRequirements(intent, capabilities) {
    const reqs = [];
    if (capabilities.canIntegrate) reqs.push('module_system');
    if (capabilities.canTransform) reqs.push('async_runtime');
    if (intent.primary.includes('browser')) reqs.push('dom_api');
    if (intent.primary.includes('node')) reqs.push('node_runtime');
    return reqs;
  }

  inferConstraints(patterns, resonance) {
    const constraints = [];
    if (patterns.includes('singleton')) constraints.push('single_instance');
    if (resonance.circuitFamily === 'ego') constraints.push('material_focus');
    return constraints;
  }

  suggestImprovements(issues) {
    return issues.map(issue => ({
      issue: issue.type,
      suggestion: this.fixSuggestion(issue.type),
      autoFixable: ['debug_code', 'legacy_var', 'loose_equality'].includes(issue.type)
    }));
  }

  fixSuggestion(issueType) {
    const suggestions = {
      debug_code: 'Remove or replace with proper logging',
      legacy_var: 'Replace var with let or const',
      loose_equality: 'Replace == with ===',
      complexity: 'Extract functions into modules',
      missing_error_handling: 'Add try/catch blocks'
    };
    return suggestions[issueType] || 'Review manually';
  }

  calculateConfidence(analysis) {
    const base = 70;
    const complexityPenalty = Math.min(20, analysis.metrics.cyclomaticComplexity);
    const patternBonus = analysis.patterns.length * 3;
    return Math.min(99, Math.max(30, base - complexityPenalty + patternBonus));
  }
}

// ============================================
// 4. REGENERATION ENGINE (Hands)
// ============================================
class MorphRegeneration {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.modes = ['exact', 'equivalent', 'morph_runtime', 'improved'];
  }

  generate({ contract, mode = 'equivalent', target = 'auto' }) {
    console.log(`[REGENERATION] Generating ${mode} version`);

    if (!this.validateContract(contract)) {
      throw new Error('Invalid contract for regeneration');
    }

    const architecture = this.selectArchitecture(contract.resonance);
    let generated;

    switch(mode) {
      case 'exact':
        generated = this.generateExact(contract);
        break;
      case 'equivalent':
        generated = this.generateEquivalent(contract, architecture);
        break;
      case 'morph_runtime':
        generated = this.generateMorphRuntime(contract, architecture);
        break;
      case 'improved':
        generated = this.generateImproved(contract, architecture);
        break;
      default:
        throw new Error(`Unknown regeneration mode: ${mode}`);
    }

    const verification = this.verifyGenerated(generated, contract);

    const result = {
      code: generated,
      mode,
      architecture,
      verification,
      contract,
      timestamp: Date.now()
    };

    console.log(`[REGENERATION] ✅ ${mode} version generated (${generated.length} chars)`);
    console.log(`[REGENERATION]    Architecture: ${architecture}`);
    console.log(`[REGENERATION]    Verification: ${verification.syntaxValid ? 'PASS' : 'FAIL'}`);

    return result;
  }

  validateContract(contract) {
    return contract && contract.intent && contract.capabilities;
  }

  selectArchitecture(resonance) {
    const circuit = resonance.circuitFamily;
    const map = MORPH_KERNEL_ENTRY.circuit_architecture_map;
    return map[circuit] || 'Auto-Select';
  }

  generateExact(contract) {
    const artifact = this.orchestrator.persistence.getArtifact(contract.artifactId);
    return artifact ? artifact.code : '';
  }

  generateEquivalent(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: false });
  }

  generateMorphRuntime(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, native: true });
  }

  generateImproved(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, improve: true, native: true });
  }

  buildFromContract(contract, architecture, options) {
    const builder = new CodeBuilder();
    const original = this.orchestrator.persistence.getArtifact(contract.artifactId);

    // Add header
    builder.addComment(`Generated by Morph OS v1.0`);
    builder.addComment(`Mode: ${options.improve ? 'improved' : options.native ? 'morph_runtime' : 'equivalent'}`);
    builder.addComment(`Architecture: ${architecture}`);
    builder.addComment(`Original: ${original.metadata.name || 'unknown'}`);
    builder.addComment(`Gate: ${contract.resonance.primaryGate} | Circuit: ${contract.resonance.circuitFamily}`);
    builder.addComment('');

    // Add imports based on dependencies
    for (const dep of original.contract.dependencies) {
      builder.addImport(dep);
    }

    // Apply improvements
    let code = original.code;

    if (options.improve) {
      // Fix var → let/const
      code = code.replace(/\bvar\b/g, 'const');

      // Fix loose equality
      code = code.replace(/([^=!])==([^=])/g, '$1===$2');

      // Remove debug logs
      code = code.replace(/console\.log\([^)]*\);?\s*\n/g, '\n');

      // Add error handling to async functions
      if (code.includes('async') && !code.includes('try')) {
        code = this.wrapWithErrorHandling(code);
      }

      // Add JSDoc comments
      code = this.addJSDocComments(code);
    }

    builder.addRaw(code);

    // Add exports
    for (const iface of original.contract.interfaces) {
      builder.addExport(iface);
    }

    return builder.build();
  }

  wrapWithErrorHandling(code) {
    // Simple wrapper - in production would be AST-based
    return code.replace(
      /async\s+function\s+(\w+)\s*\([^)]*\)\s*\{/g,
      'async function $1(...) { try {'
    ).replace(
      /\}\s*$/,
      '} catch (error) { console.error(`Error in $1:`, error); throw error; } }'
    );
  }

  addJSDocComments(code) {
    // Add JSDoc to functions
    return code.replace(
      /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g,
      (match, name, params) => {
        const paramDocs = params.split(',').filter(p => p.trim()).map(p => ` * @param {any} ${p.trim()}`).join('\n');
        return `/**\n * ${name}\n${paramDocs}\n * @returns {any}\n */\n${match}`;
      }
    );
  }

  verifyGenerated(generated, contract) {
    return {
      syntaxValid: this.checkSyntax(generated),
      behaviorMatch: this.checkBehavior(generated, contract),
      patternMatch: this.checkPatterns(generated, contract.patterns),
      resonanceMatch: this.checkResonance(generated, contract.resonance)
    };
  }

  checkSyntax(code) {
    try {
      new Function(code);
      return true;
    } catch (e) {
      return false;
    }
  }

  checkBehavior(code, contract) {
    const hasOriginalPatterns = contract.patterns.every(p => {
      if (p === 'observer') return code.includes('Event') || code.includes('Listener');
      if (p === 'factory') return code.includes('create') || code.includes('new');
      if (p === 'singleton') return code.includes('getInstance') || /if\s*\(!?\w+\)/.test(code);
      return true;
    });
    return hasOriginalPatterns;
  }

  checkPatterns(code, patterns) {
    return patterns.filter(p => {
      if (p === 'observer') return code.includes('Event') || code.includes('Listener');
      if (p === 'factory') return code.includes('create') || code.includes('new');
      if (p === 'singleton') return code.includes('getInstance');
      if (p === 'async_pattern') return code.includes('async') || code.includes('Promise');
      if (p === 'error_handling') return code.includes('try') && code.includes('catch');
      return true;
    }).length === patterns.length;
  }

  checkResonance(code, resonance) {
    const circuit = resonance.circuitFamily;
    if (circuit === 'knowing' && !code.includes('class')) return false;
    if (circuit === 'understanding' && !code.includes('function')) return false;
    return true;
  }
}

