class CodeBuilder {
  constructor() {
    this.parts = [];
  }

  addComment(text) {
    this.parts.push(`// ${text}`);
  }

  addImport(name) {
    this.parts.push(`import { ${name} } from '${name}';`);
  }

  addExport(name) {
    this.parts.push(`export { ${name} };`);
  }

  addRaw(code) {
