// 2. STUDY MODULE (Eyes)
// ============================================
class MorphStudy {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
  }

  analyze(artifactId) {
    console.log(`[STUDY] Analyzing artifact ${artifactId}`);

    const artifact = this.orchestrator.persistence.getArtifact(artifactId);
    if (!artifact) throw new Error(`Artifact ${artifactId} not found`);

    const structure = this.analyzeStructure(artifact.cpg);
    const semantics = this.analyzeSemantics(artifact.cpg);
    const patterns = this.recognizePatterns(artifact.cpg);
    const metrics = this.calculateMetrics(artifact.cpg);
    const resonance = this.mapToResonance(artifact.contract);
    const issues = this.findIssues(artifact.code);

    const analysis = {
      artifactId,
      structure,
      semantics,
      patterns,
      metrics,
      resonance,
      issues,
      timestamp: Date.now()
    };

    console.log(`[STUDY] ✅ Analysis complete for ${artifactId}`);
    console.log(`[STUDY]    Nodes: ${structure.nodeCount}, Complexity: ${metrics.cyclomaticComplexity}`);
    console.log(`[STUDY]    Patterns: ${patterns.join(', ') || 'none'}`);
    console.log(`[STUDY]    Issues: ${issues.length} found`);

    return analysis;
  }

  analyzeStructure(cpg) {
    return {
      nodeCount: cpg.nodes.length,
      edgeCount: cpg.edges.length,
      depth: cpg.complexity.functions,
      breadth: cpg.complexity.classes,
      cyclomaticComplexity: cpg.complexity.cyclomatic,
      linesOfCode: cpg.complexity.lines
    };
  }

  analyzeSemantics(cpg) {
    return {
      dataFlow: cpg.dataFlow,
      controlFlow: cpg.controlFlow,
      complexity: cpg.complexity
    };
  }

  recognizePatterns(cpg) {
    return cpg.patterns || [];
  }

  calculateMetrics(cpg) {
    return {
      ...cpg.complexity,
      maintainability: Math.max(0, 100 - cpg.complexity.cyclomatic * 2 - cpg.complexity.lines / 10)
    };
  }

  mapToResonance(contract) {
    const primaryGate = this.inferPrimaryGate(contract);
    return {
      primaryGate,
      activeChannels: this.inferChannels(primaryGate),
      circuitFamily: this.inferCircuitFamily(primaryGate),
      consciousnessLevel: this.inferConsciousnessLevel(contract)
    };
  }

  inferPrimaryGate(contract) {
    const intents = contract.intent.split(', ');
    if (intents.includes('async')) return 20;
    if (intents.includes('object_oriented')) return 1;
    if (intents.includes('functional')) return 4;
    if (intents.includes('network')) return 14;
    if (intents.includes('browser')) return 10;
    if (intents.includes('node')) return 57;
    return 1;
  }

  inferChannels(gate) {
    const channels = [];
    for (const [circuitName, circuit] of Object.entries(TRIDENT_GNN.channels)) {
      for (const [channelName, channel] of Object.entries(circuit.channels || {})) {
        if (channel.gates.includes(gate)) {
          channels.push(channelName);
        }
      }
    }
    return channels;
  }

  inferCircuitFamily(gate) {
    for (const [name, circuit] of Object.entries(TRIDENT_GNN.circuits)) {
      if (circuit.gates.includes(gate)) return name;
    }
    return 'integration';
  }

  inferConsciousnessLevel(contract) {
    const complexity = contract.complexity;
    if (complexity.cyclomatic > 20) return 3;
    if (complexity.functions > 10) return 2;
    if (complexity.classes > 0) return 2;
    return 1;
  }

  findIssues(code) {
    const issues = [];

    // Check for common problems
    if (code.includes('console.log')) {
      issues.push({ type: 'debug_code', severity: 'low', message: 'Debug console.log statements found' });
    }
    if (code.includes('var ')) {
      issues.push({ type: 'legacy_var', severity: 'medium', message: 'Use of var instead of let/const' });
    }
    if (code.includes('==') && !code.includes('===')) {
      issues.push({ type: 'loose_equality', severity: 'medium', message: 'Loose equality (==) detected, use strict (===)' });
    }
    if ((code.match(/function/g) || []).length > 15) {
      issues.push({ type: 'complexity', severity: 'high', message: 'High function count - consider splitting' });
    }
    if (!code.includes('try') && code.includes('await')) {
      issues.push({ type: 'missing_error_handling', severity: 'high', message: 'Async code without error handling' });
    }

    return issues;
  }
}

