// 4. REGENERATION ENGINE (Hands)
// ============================================
class MorphRegeneration {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.modes = ['exact', 'equivalent', 'morph_runtime', 'improved'];
  }

  generate({ contract, mode = 'equivalent', target = 'auto' }) {
    console.log(`[REGENERATION] Generating ${mode} version`);

    if (!this.validateContract(contract)) {
      throw new Error('Invalid contract for regeneration');
    }

    const architecture = this.selectArchitecture(contract.resonance);
    let generated;

    switch(mode) {
      case 'exact':
        generated = this.generateExact(contract);
        break;
      case 'equivalent':
        generated = this.generateEquivalent(contract, architecture);
        break;
      case 'morph_runtime':
        generated = this.generateMorphRuntime(contract, architecture);
        break;
      case 'improved':
        generated = this.generateImproved(contract, architecture);
        break;
      default:
        throw new Error(`Unknown regeneration mode: ${mode}`);
    }

    const verification = this.verifyGenerated(generated, contract);

    const result = {
      code: generated,
      mode,
      architecture,
      verification,
      contract,
      timestamp: Date.now()
    };

    console.log(`[REGENERATION] ✅ ${mode} version generated (${generated.length} chars)`);
    console.log(`[REGENERATION]    Architecture: ${architecture}`);
    console.log(`[REGENERATION]    Verification: ${verification.syntaxValid ? 'PASS' : 'FAIL'}`);

    return result;
  }

  validateContract(contract) {
    return contract && contract.intent && contract.capabilities;
  }

  selectArchitecture(resonance) {
    const circuit = resonance.circuitFamily;
    const map = MORPH_KERNEL_ENTRY.circuit_architecture_map;
    return map[circuit] || 'Auto-Select';
  }

  generateExact(contract) {
    const artifact = this.orchestrator.persistence.getArtifact(contract.artifactId);
    return artifact ? artifact.code : '';
  }

  generateEquivalent(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: false });
  }

  generateMorphRuntime(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, native: true });
  }

  generateImproved(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, improve: true, native: true });
  }

  buildFromContract(contract, architecture, options) {
    const builder = new CodeBuilder();
    const original = this.orchestrator.persistence.getArtifact(contract.artifactId);

    // Add header
    builder.addComment(`Generated by Morph OS v1.0`);
    builder.addComment(`Mode: ${options.improve ? 'improved' : options.native ? 'morph_runtime' : 'equivalent'}`);
    builder.addComment(`Architecture: ${architecture}`);
    builder.addComment(`Original: ${original.metadata.name || 'unknown'}`);
    builder.addComment(`Gate: ${contract.resonance.primaryGate} | Circuit: ${contract.resonance.circuitFamily}`);
    builder.addComment('');

    // Add imports based on dependencies
    for (const dep of original.contract.dependencies) {
      builder.addImport(dep);
    }

    // Apply improvements
    let code = original.code;

    if (options.improve) {
      // Fix var → let/const
      code = code.replace(/\bvar\b/g, 'const');

      // Fix loose equality
      code = code.replace(/([^=!])==([^=])/g, '$1===$2');

      // Remove debug logs
      code = code.replace(/console\.log\([^)]*\);?\s*\n/g, '\n');

      // Add error handling to async functions
      if (code.includes('async') && !code.includes('try')) {
        code = this.wrapWithErrorHandling(code);
      }

      // Add JSDoc comments
      code = this.addJSDocComments(code);
    }

    builder.addRaw(code);

    // Add exports
    for (const iface of original.contract.interfaces) {
      builder.addExport(iface);
    }

    return builder.build();
  }

  wrapWithErrorHandling(code) {
    // Simple wrapper - in production would be AST-based
    return code.replace(
      /async\s+function\s+(\w+)\s*\([^)]*\)\s*\{/g,
      'async function $1(...) { try {'
    ).replace(
      /\}\s*$/,
      '} catch (error) { console.error(`Error in $1:`, error); throw error; } }'
    );
  }

  addJSDocComments(code) {
    // Add JSDoc to functions
    return code.replace(
      /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g,
      (match, name, params) => {
        const paramDocs = params.split(',').filter(p => p.trim()).map(p => ` * @param {any} ${p.trim()}`).join('\n');
        return `/**\n * ${name}\n${paramDocs}\n * @returns {any}\n */\n${match}`;
      }
    );
  }

  verifyGenerated(generated, contract) {
    return {
      syntaxValid: this.checkSyntax(generated),
      behaviorMatch: this.checkBehavior(generated, contract),
      patternMatch: this.checkPatterns(generated, contract.patterns),
      resonanceMatch: this.checkResonance(generated, contract.resonance)
    };
  }

  checkSyntax(code) {
    try {
      new Function(code);
      return true;
    } catch (e) {
      return false;
    }
  }

  checkBehavior(code, contract) {
    const hasOriginalPatterns = contract.patterns.every(p => {
      if (p === 'observer') return code.includes('Event') || code.includes('Listener');
      if (p === 'factory') return code.includes('create') || code.includes('new');
      if (p === 'singleton') return code.includes('getInstance') || /if\s*\(!?\w+\)/.test(code);
      return true;
    });
    return hasOriginalPatterns;
  }

  checkPatterns(code, patterns) {
    return patterns.filter(p => {
      if (p === 'observer') return code.includes('Event') || code.includes('Listener');
      if (p === 'factory') return code.includes('create') || code.includes('new');
      if (p === 'singleton') return code.includes('getInstance');
      if (p === 'async_pattern') return code.includes('async') || code.includes('Promise');
      if (p === 'error_handling') return code.includes('try') && code.includes('catch');
      return true;
    }).length === patterns.length;
  }

  checkResonance(code, resonance) {
    const circuit = resonance.circuitFamily;
    if (circuit === 'knowing' && !code.includes('class')) return false;
    if (circuit === 'understanding' && !code.includes('function')) return false;
    return true;
  }
}

