      console.log('[PERSISTENCE] State saved to disk');
    } catch (e) {
      console.error(`[PERSISTENCE] Save failed: ${e.message}`);
    }
  }

  storeArtifact(id, artifact) {
    this.artifacts[id] = artifact;
    this.dirty = true;
