// 5. INTEGRATION SCHEDULER (Kernel)
// ============================================
class IntegrationScheduler {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.integrationGates = [10, 20, 34, 57];
    this.integrationChannels = [
      [10, 20], [10, 34], [10, 57],
      [20, 34], [20, 57], [34, 57]
    ];
    this.processQueue = [];
    this.consciousnessLevel = 0;
  }

  routeThroughIntegration(operation) {
    const sourceCircuit = this.inferSourceCircuit(operation);
    const targetCircuit = this.inferTargetCircuit(operation);

    if (sourceCircuit !== targetCircuit) {
      const integrationGate = this.selectIntegrationGate(sourceCircuit, targetCircuit);
      this.updateConsciousness(integrationGate);

      return {
        path: [sourceCircuit, integrationGate, targetCircuit],
        consciousnessLevel: this.consciousnessLevel,
        requiresIntegration: true
      };
    }

    return {
      path: [sourceCircuit, targetCircuit],
      consciousnessLevel: this.consciousnessLevel,
      requiresIntegration: false
    };
  }

  inferSourceCircuit(operation) {
    const map = { 'INGEST': 'sensing', 'STUDY': 'knowing', 'UNDERSTAND': 'understanding', 'REGENERATE': 'ego', 'EXECUTE': 'integration' };
    return map[operation] || 'integration';
  }

  inferTargetCircuit(operation) {
    const map = { 'INGEST': 'sensing', 'STUDY': 'knowing', 'UNDERSTAND': 'understanding', 'REGENERATE': 'ego', 'EXECUTE': 'integration' };
    return map[operation] || 'integration';
  }

  selectIntegrationGate(source, target) {
    const pair = [source, target].sort();
    if (pair.includes('knowing') && pair.includes('understanding')) return 10;
    if (pair.includes('sensing') && pair.includes('understanding')) return 20;
    if (pair.includes('ego') && pair.includes('understanding')) return 34;
    if (pair.includes('knowing') && pair.includes('sensing')) return 57;
    return 10;
  }

  updateConsciousness(activeGate) {
    this.orchestrator.gnn.activateGate(activeGate, 'scheduler');
    const activeGates = this.integrationGates.filter(g => this.orchestrator.gnn.isGateActive(g));
    this.consciousnessLevel = activeGates.length;

    const levels = MORPH_KERNEL_ENTRY.consciousness_levels;
    console.log(`[SCHEDULER] Consciousness level: ${this.consciousnessLevel} - ${levels[this.consciousnessLevel]}`);
  }
}

