// 6. TRIDENT GNN (Native Instruction Set)
// ============================================
class TridentGNN {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.activeGates = new Set();
    this.activeChannels = new Set();
    this.architectureInstances = new Map();
    this.representations = new Map();
  }

  loadGeometry(system) {
    this.geometry = TRIDENT_GNN.coordinate_systems[system];
  }

  loadSequence(system) {
    this.sequence = TRIDENT_GNN.coordinate_systems[system];
  }

  loadDomain(system) {
    this.domain = TRIDENT_GNN.coordinate_systems[system];
  }

  verifyStructure(system) {
    this.structure = TRIDENT_GNN.coordinate_systems[system];
  }

  loadContrast(system) {
    this.contrast = TRIDENT_GNN.coordinate_systems[system];
  }

  activateGate(gateId, planetaryLayer) {
    this.activeGates.add(gateId);
    this.checkChannelFormation(gateId);
  }

  deactivateGate(gateId) {
    this.activeGates.delete(gateId);
  }

  isGateActive(gateId) {
    return this.activeGates.has(gateId);
  }

  checkChannelFormation(gateId) {
    for (const [circuitName, circuit] of Object.entries(TRIDENT_GNN.channels)) {
      for (const [channelName, channel] of Object.entries(circuit.channels || {})) {
        if (channel.gates && channel.gates.includes(gateId)) {
          const otherGate = channel.gates.find(g => g !== gateId);
          if (this.isGateActive(otherGate)) {
            this.formChannel(channelName, channel);
          }
        }
      }
    }
  }

  formChannel(channelName, channelData) {
    this.activeChannels.add(channelName);
    this.architectureInstances.set(channelName, {
      type: channelData.architecture,
      data: channelData,
      state: 'stable'
    });
  }

  passMessage(source, target, payload) {
    const channel = this.findChannel(source, target);
    if (!channel) {
      throw new Error(`No channel between ${source} and ${target}`);
    }
    const architecture = this.architectureInstances.get(channel);
    return this.transformThroughArchitecture(payload, architecture);
  }

  findChannel(gateA, gateB) {
    for (const channelName of this.activeChannels) {
      for (const [circuitName, circuit] of Object.entries(TRIDENT_GNN.channels)) {
        const channelData = circuit.channels && circuit.channels[channelName];
