      controlFlow: cpg.controlFlow,
      complexity: cpg.complexity
    };
  }

  recognizePatterns(cpg) {
    return cpg.patterns || [];
  }

  calculateMetrics(cpg) {
    return {
      ...cpg.complexity,
      maintainability: Math.max(0, 100 - cpg.complexity.cyclomatic * 2 - cpg.complexity.lines / 10)
    };
  }

  mapToResonance(contract) {
    const primaryGate = this.inferPrimaryGate(contract);
    return {
      primaryGate,
      activeChannels: this.inferChannels(primaryGate),
      circuitFamily: this.inferCircuitFamily(primaryGate),
      consciousnessLevel: this.inferConsciousnessLevel(contract)
    };
