  inferPrimaryGate(contract) {
    const intents = contract.intent.split(', ');
    if (intents.includes('async')) return 20;
    if (intents.includes('object_oriented')) return 1;
    if (intents.includes('functional')) return 4;
    if (intents.includes('network')) return 14;
    if (intents.includes('browser')) return 10;
    if (intents.includes('node')) return 57;
    return 1;
  }

  inferChannels(gate) {
    const channels = [];
    for (const [circuitName, circuit] of Object.entries(TRIDENT_GNN.channels)) {
      for (const [channelName, channel] of Object.entries(circuit.channels || {})) {
        if (channel.gates.includes(gate)) {
          channels.push(channelName);
        }
      }
    }
    return channels;
  }

  inferCircuitFamily(gate) {
    for (const [name, circuit] of Object.entries(TRIDENT_GNN.circuits)) {
      if (circuit.gates.includes(gate)) return name;
    }
    return 'integration';
  }

  inferConsciousnessLevel(contract) {
    const complexity = contract.complexity;
    if (complexity.cyclomatic > 20) return 3;
    if (complexity.functions > 10) return 2;
    if (complexity.classes > 0) return 2;
    return 1;
  }

  findIssues(code) {
    const issues = [];

    // Check for common problems
    if (code.includes('console.log')) {
      issues.push({ type: 'debug_code', severity: 'low', message: 'Debug console.log statements found' });
    }
    if (code.includes('var ')) {
      issues.push({ type: 'legacy_var', severity: 'medium', message: 'Use of var instead of let/const' });
    }
    if (code.includes('==') && !code.includes('===')) {
      issues.push({ type: 'loose_equality', severity: 'medium', message: 'Loose equality (==) detected, use strict (===)' });
    }
    if ((code.match(/function/g) || []).length > 15) {
      issues.push({ type: 'complexity', severity: 'high', message: 'High function count - consider splitting' });
    }
    if (!code.includes('try') && code.includes('await')) {
      issues.push({ type: 'missing_error_handling', severity: 'high', message: 'Async code without error handling' });
    }

    return issues;
  }
}

