// ============================================
// 8. CODE BUILDER
// ============================================
class CodeBuilder {
  constructor() {
    this.parts = [];
  }

  addComment(text) {
    this.parts.push(`// ${text}`);
  }

  addImport(name) {
    this.parts.push(`import { ${name} } from '${name}';`);
  }

  addExport(name) {
    this.parts.push(`export { ${name} };`);
  }

  addRaw(code) {
    this.parts.push(code);
  }

  addStructure(intent) {
    const name = intent.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('');
    this.parts.push(`class ${name} { constructor() { this.intent = '${intent}'; } }`);
  }

  addMethod(capability) {
    this.parts.push(`  ${capability}() { // Capability: ${capability} }`);
  }

  addPattern(pattern) {
    this.parts.push(`// Pattern: ${pattern}`);
  }

  addResonanceHooks(resonance) {
    this.parts.push(`// Resonance: Gate ${resonance.primaryGate}, Circuit: ${resonance.circuitFamily}`);
  }

  build() {
    return this.parts.join('\n');
  }
}

// ============================================
// 9. PARSERS
// ============================================
class JSParser {
  parse(code) {
    const nodes = [];
    const functionMatches = code.match(/function\s+(\w+)/g) || [];
    const classMatches = code.match(/class\s+(\w+)/g) || [];
    const constMatches = code.match(/(?:const|let|var)\s+(\w+)\s*=/g) || [];

    for (const match of functionMatches) {
      nodes.push({ type: 'function', name: match.replace('function ', '') });
    }
    for (const match of classMatches) {
      nodes.push({ type: 'class', name: match.replace('class ', '') });
    }
    for (const match of constMatches) {
      nodes.push({ type: 'variable', name: match.replace(/(?:const|let|var)\s+/, '').replace('=', '').trim() });
    }

    return { type: 'js', code, nodes, edges: [] };
  }
}

class PythonParser {
  parse(code) {
    const nodes = [];
    const funcMatches = code.match(/def\s+(\w+)/g) || [];
    const classMatches = code.match(/class\s+(\w+)/g) || [];
    for (const m of funcMatches) nodes.push({ type: 'function', name: m.replace('def ', '') });
    for (const m of classMatches) nodes.push({ type: 'class', name: m.replace('class ', '') });
    return { type: 'py', code, nodes, edges: [] };
  }
}

class YAMLParser {
  parse(code) {
    return { type: 'yaml', code, nodes: [{ type: 'document', name: 'yaml_doc' }], edges: [] };
  }
}

class JSONParser {
  parse(code) {
    try {
      const data = JSON.parse(code);
      return { type: 'json', code, data, nodes: [{ type: 'object', name: 'root' }], edges: [] };
    } catch (e) {
      return { type: 'json', code, nodes: [], edges: [] };
    }
  }
}

class HTMLParser {
  parse(code) {
    const tags = (code.match(/<(\w+)/g) || []).map(t => t.slice(1));
    return { type: 'html', code, nodes: tags.map(t => ({ type: 'element', name: t })), edges: [] };
  }
}

class CSSParser {
  parse(code) {
    const selectors = (code.match(/([.#]?[\w-]+)\s*\{/g) || []).map(s => s.replace('{', '').trim());
    return { type: 'css', code, nodes: selectors.map(s => ({ type: 'selector', name: s })), edges: [] };
  }
}

