      case 'REGENERATE':
        return this.regeneration.generate({
          contract: params.contract,
          mode: params.mode || 'equivalent',
          target: params.target || 'auto'
        });
      case 'EXECUTE':
        return this.gnn.executeProcess(params.processId);
      default:
        throw new Error(`Unknown operation: ${operation}`);
    }
  }

  selfImprove() {
    console.log('[MORPH-OS] Self-improvement cycle initiated');

    const kernelCode = fs.readFileSync(__filename, 'utf8');
    const artifactId = this.ingestion.ingest(kernelCode, { type: 'js', version: '1.0', name: 'morph-os-kernel' });

    this.study.analyze(artifactId);
    const understanding = this.understanding.buildRepresentation(artifactId);
    const improved = this.regeneration.generate({
