  }

  shutdown() {
    console.log('[MORPH-OS] Shutting down...');
    this.persistence.flush();
    console.log('[MORPH-OS] State persisted. Goodbye.');
  }
}

// ============================================
// 1. INGESTION ENGINE (Mouth)
// ============================================
class MorphIngestion {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.parsers = {
      'js': new JSParser(),
      'py': new PythonParser(),
      'yaml': new YAMLParser(),
      'json': new JSONParser(),
      'html': new HTMLParser(),
      'css': new CSSParser()
    };
  }

  ingest(code, metadata = {}) {
    console.log(`[INGESTION] Ingesting ${metadata.type || 'unknown'} artifact: ${metadata.name || 'unnamed'}`);

    const parser = this.parsers[metadata.type] || this.parsers['js'];
    const ast = parser.parse(code);
    const cpg = this.buildCPG(ast, code);
    const contract = this.extractContract(cpg, code);

    const artifactId = `artifact_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const artifact = {
      id: artifactId,
      code,
      ast,
      cpg,
      contract,
      metadata,
      timestamp: Date.now(),
      size: code.length
    };

    this.orchestrator.persistence.storeArtifact(artifactId, artifact);
    this.orchestrator.gnn.ingestArtifact(artifact);

    console.log(`[INGESTION] ✅ Artifact ${artifactId} stored (${code.length} chars)`);
    return artifactId;
  }

  ingestFile(filepath) {
    const code = fs.readFileSync(filepath, 'utf8');
    const ext = path.extname(filepath).slice(1);
    const name = path.basename(filepath);
    return this.ingest(code, { type: ext, name, path: filepath });
  }

  buildCPG(ast, code) {
    return {
      nodes: this.extractNodes(ast),
      edges: this.extractEdges(ast),
      dataFlow: this.extractDataFlow(ast, code),
      controlFlow: this.extractControlFlow(ast, code),
      complexity: this.calculateComplexity(code)
    };
  }

  extractNodes(ast) {
    return ast.nodes || [];
  }

  extractEdges(ast) {
    return ast.edges || [];
  }

  extractDataFlow(ast, code) {
    const assignments = (code.match(/\b(let|const|var)\s+\w+\s*=/g) || []).length;
    const mutations = (code.match(/\w+\s*=\s*[^=]/g) || []).length;
    return { assignments, mutations, dataSources: [] };
  }

  extractControlFlow(ast, code) {
    const conditionals = (code.match(/\b(if|else|switch|case)\b/g) || []).length;
    const loops = (code.match(/\b(for|while|do)\b/g) || []).length;
    const returns = (code.match(/\breturn\b/g) || []).length;
    return { conditionals, loops, returns };
  }

  calculateComplexity(code) {
    const lines = code.split('\n').length;
    const functions = (code.match(/\bfunction\b/g) || []).length;
    const classes = (code.match(/\bclass\b/g) || []).length;
    const branches = (code.match(/\b(if|else|switch|case|for|while)\b/g) || []).length;
    return { lines, functions, classes, branches, cyclomatic: branches + 1 };
  }

  extractContract(cpg, code) {
    return {
      intent: this.inferIntent(code),
      functions: this.extractFunctions(code),
      dependencies: this.extractDependencies(code),
      interfaces: this.extractInterfaces(code),
      patterns: this.recognizePatterns(code),
      complexity: cpg.complexity
    };
  }

  inferIntent(code) {
    const intents = [];
    if (code.includes('class')) intents.push('object_oriented');
    if (code.includes('function')) intents.push('functional');
    if (code.includes('async') || code.includes('await')) intents.push('async');
    if (code.includes('import') || code.includes('require')) intents.push('modular');
    if (code.includes('export')) intents.push('library');
    if (code.includes('console.log')) intents.push('debug');
    if (code.includes('fetch') || code.includes('http')) intents.push('network');
    if (code.includes('document') || code.includes('window')) intents.push('browser');
    if (code.includes('process') || code.includes('fs.')) intents.push('node');
    return intents.length > 0 ? intents.join(', ') : 'general';
  }

  extractFunctions(code) {
    const funcs = [];
    const funcRegex = /(?:function\s+(\w+)|(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s*)?(?:function|\([^)]*\)\s*=>))/g;
    let match;
    while ((match = funcRegex.exec(code)) !== null) {
      funcs.push(match[1] || match[2]);
    }
    return funcs;
  }

  extractDependencies(code) {
    const deps = [];
    const importRegex = /(?:import\s+.*?\s+from\s+['"]([^'"]+)['"]|require\s*\(\s*['"]([^'"]+)['"]\s*\))/g;
    let match;
    while ((match = importRegex.exec(code)) !== null) {
      deps.push(match[1] || match[2]);
    }
    return deps;
  }

  extractInterfaces(code) {
    const interfaces = [];
    if (code.includes('module.exports')) interfaces.push('commonjs');
    if (code.includes('export default')) interfaces.push('esm_default');
    if (code.includes('export {')) interfaces.push('esm_named');
    if (code.includes('export class')) interfaces.push('esm_class');
    return interfaces;
  }

  recognizePatterns(code) {
    const patterns = [];
    if (code.includes('new Event') || code.includes('addEventListener') || /on\w+\s*=/.test(code)) patterns.push('observer');
    if (code.includes('new ') && code.includes('create')) patterns.push('factory');
    if (code.includes('getInstance') || /if\s*\(!?\w+\)/.test(code)) patterns.push('singleton');
    if (code.includes('class') && code.includes('extends')) patterns.push('inheritance');
    if (code.includes('Promise') || code.includes('async')) patterns.push('async_pattern');
    if (code.includes('try') && code.includes('catch')) patterns.push('error_handling');
    return patterns;
  }
}

// ============================================
// 2. STUDY MODULE (Eyes)
// ============================================
class MorphStudy {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.analyses = new Map();
  }

  analyze(artifactId) {
    // Check if already analyzed
    if (this.analyses && this.analyses.has && this.analyses.has(artifactId)) {
      console.log(`[STUDY] Using cached analysis for ${artifactId}`);
      return this.analyses.get(artifactId);
    }
    console.log(`[STUDY] Cache miss - analyzing fresh`);

    console.log(`[STUDY] Analyzing artifact ${artifactId}`);

    const artifact = this.orchestrator.persistence.getArtifact(artifactId);
    if (!artifact) throw new Error(`Artifact ${artifactId} not found`);

    const structure = this.analyzeStructure(artifact.cpg);
    const semantics = this.analyzeSemantics(artifact.cpg);
    const patterns = this.recognizePatterns(artifact.cpg);
    const metrics = this.calculateMetrics(artifact.cpg);
    const resonance = this.mapToResonance(artifact.contract);
    const issues = this.findIssues(artifact.code);

    const analysis = {
      artifactId,
      structure,
      semantics,
      patterns,
      metrics,
      resonance,
      issues,
      timestamp: Date.now()
    };

    this.analyses.set(artifactId, analysis);

    console.log(`[STUDY] ✅ Analysis complete for ${artifactId}`);
    console.log(`[STUDY]    Nodes: ${structure.nodeCount}, Complexity: ${metrics.cyclomaticComplexity || structure.cyclomaticComplexity}`);
    console.log(`[STUDY]    Patterns: ${patterns.join(', ') || 'none'}`);
    console.log(`[STUDY]    Issues: ${issues.length} found`);

    return analysis;
  }

  analyzeStructure(cpg) {
    return {
      nodeCount: cpg.nodes.length,
      edgeCount: cpg.edges.length,
      depth: cpg.complexity.functions,
      breadth: cpg.complexity.classes,
      cyclomaticComplexity: cpg.complexity.cyclomatic,
      linesOfCode: cpg.complexity.lines
    };
  }

  analyzeSemantics(cpg) {
    return {
      dataFlow: cpg.dataFlow,
      controlFlow: cpg.controlFlow,
      complexity: cpg.complexity
    };
  }

  recognizePatterns(cpg) {
    return cpg.patterns || [];
  }

  calculateMetrics(cpg) {
    return {
      ...cpg.complexity,
      maintainability: Math.max(0, 100 - cpg.complexity.cyclomatic * 2 - cpg.complexity.lines / 10)
    };
  }

  mapToResonance(contract) {
    const primaryGate = this.inferPrimaryGate(contract);
    return {
      primaryGate,
      activeChannels: this.inferChannels(primaryGate),
      circuitFamily: this.inferCircuitFamily(primaryGate),
      consciousnessLevel: this.inferConsciousnessLevel(contract)
    };
  }

  inferPrimaryGate(contract) {
    const intents = contract.intent.split(', ');
    if (intents.includes('async')) return 20;
    if (intents.includes('object_oriented')) return 1;
    if (intents.includes('functional')) return 4;
    if (intents.includes('network')) return 14;
    if (intents.includes('browser')) return 10;
    if (intents.includes('node')) return 57;
    return 1;
  }

  inferChannels(gate) {
    const channels = [];
    for (const [circuitName, circuit] of Object.entries(TRIDENT_GNN.channels)) {
      for (const [channelName, channel] of Object.entries(circuit.channels || {})) {
        if (channel.gates.includes(gate)) {
          channels.push(channelName);
        }
      }
    }
    return channels;
  }

  inferCircuitFamily(gate) {
    for (const [name, circuit] of Object.entries(TRIDENT_GNN.circuits)) {
      if (circuit.gates.includes(gate)) return name;
    }
    return 'integration';
  }

  inferConsciousnessLevel(contract) {
    const complexity = contract.complexity;
    if (complexity.cyclomatic > 20) return 3;
    if (complexity.functions > 10) return 2;
    if (complexity.classes > 0) return 2;
    return 1;
  }

  findIssues(code) {
    const issues = [];

    // Check for common problems
    if (code.includes('console.log')) {
      issues.push({ type: 'debug_code', severity: 'low', message: 'Debug console.log statements found' });
    }
    if (code.includes('var ')) {
      issues.push({ type: 'legacy_var', severity: 'medium', message: 'Use of var instead of let/const' });
    }
    if (code.includes('==') && !code.includes('===')) {
      issues.push({ type: 'loose_equality', severity: 'medium', message: 'Loose equality (==) detected, use strict (===)' });
    }
    if ((code.match(/function/g) || []).length > 15) {
      issues.push({ type: 'complexity', severity: 'high', message: 'High function count - consider splitting' });
    }
    if (!code.includes('try') && code.includes('await')) {
      issues.push({ type: 'missing_error_handling', severity: 'high', message: 'Async code without error handling' });
    }

    return issues;
  }
}

// ============================================
// 3. UNDERSTANDING LAYER (Brain)
// ============================================
class MorphUnderstanding {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
  }

  buildRepresentation(artifactId) {
    console.log(`[UNDERSTANDING] Building representation for ${artifactId}`);

    const artifact = this.orchestrator.persistence.getArtifact(artifactId);
    if (!artifact) throw new Error(`Artifact ${artifactId} not found`);

    // Get analysis (will use cache if already studied)
    const analysis = this.orchestrator.study.analyze(artifactId);

    const embedding = this.createEmbedding(artifact, analysis);
    const intent = this.extractIntent(artifact.contract);
    const capabilities = this.mapCapabilities(artifact.contract);
    const formalContract = this.formalizeContract({
      artifactId,
      intent,
      capabilities,
      patterns: analysis.patterns,
      resonance: analysis.resonance,
      issues: analysis.issues
    });

    const representation = {
      artifactId,
      embedding,
      intent,
      capabilities,
      contract: formalContract,
      confidence: this.calculateConfidence(analysis),
      timestamp: Date.now()
    };

    this.orchestrator.persistence.storeContract(artifactId, formalContract);
    this.orchestrator.gnn.storeRepresentation(representation);

    console.log(`[UNDERSTANDING] ✅ Representation built for ${artifactId}`);
    console.log(`[UNDERSTANDING]    Intent: ${intent.primary}`);
    console.log(`[UNDERSTANDING]    Confidence: ${representation.confidence.toFixed(2)}%`);

    return representation;
  }

  createEmbedding(artifact, analysis) {
    return {
      vector: [artifact.cpg.complexity.lines, artifact.cpg.complexity.functions, artifact.cpg.complexity.cyclomatic],
      center: analysis.resonance.primaryGate % 9,
      hexagram: analysis.resonance.primaryGate,
      dimensions: {
        lines: artifact.cpg.complexity.lines,
        functions: artifact.cpg.complexity.functions,
        classes: artifact.cpg.complexity.classes,
        branches: artifact.cpg.complexity.branches
      }
    };
  }

  extractIntent(contract) {
    return {
      primary: contract.intent,
      secondary: contract.patterns.join(', ') || 'none',
      implicit: contract.dependencies.length > 0 ? 'modular' : 'standalone'
    };
  }

  mapCapabilities(contract) {
    return {
      canCreate: contract.complexity.functions > 0,
      canRead: contract.intent.includes('node') || contract.intent.includes('network'),
      canUpdate: contract.patterns.includes('observer') || contract.patterns.includes('factory'),
      canDelete: contract.patterns.includes('error_handling'),
      canTransform: contract.patterns.includes('async_pattern'),
      canIntegrate: contract.interfaces.length > 0
    };
  }

  formalizeContract({ intent, capabilities, patterns, resonance, issues, artifactId }) {
    return {
      type: 'morph_contract',
      version: '1.0',
      artifactId,
      intent,
      capabilities,
      patterns,
      resonance,
      issues,
      requirements: this.inferRequirements(intent, capabilities),
      constraints: this.inferConstraints(patterns, resonance),
      improvements: this.suggestImprovements(issues)
    };
  }

  inferRequirements(intent, capabilities) {
    const reqs = [];
    if (capabilities.canIntegrate) reqs.push('module_system');
    if (capabilities.canTransform) reqs.push('async_runtime');
    if (intent.primary.includes('browser')) reqs.push('dom_api');
    if (intent.primary.includes('node')) reqs.push('node_runtime');
    return reqs;
  }

  inferConstraints(patterns, resonance) {
    const constraints = [];
    if (patterns.includes('singleton')) constraints.push('single_instance');
    if (resonance.circuitFamily === 'ego') constraints.push('material_focus');
    return constraints;
  }

  suggestImprovements(issues) {
    return issues.map(issue => ({
      issue: issue.type,
      suggestion: this.fixSuggestion(issue.type),
      autoFixable: ['debug_code', 'legacy_var', 'loose_equality'].includes(issue.type)
    }));
  }

  fixSuggestion(issueType) {
    const suggestions = {
      debug_code: 'Remove or replace with proper logging',
      legacy_var: 'Replace var with let or const',
      loose_equality: 'Replace == with ===',
      complexity: 'Extract functions into modules',
      missing_error_handling: 'Add try/catch blocks'
    };
    return suggestions[issueType] || 'Review manually';
  }

  calculateConfidence(analysis) {
    const base = 70;
    const complexityPenalty = Math.min(20, analysis.metrics.cyclomaticComplexity);
    const patternBonus = analysis.patterns.length * 3;
    return Math.min(99, Math.max(30, base - complexityPenalty + patternBonus)) || 50;
  }
}

// ============================================
// 4. REGENERATION ENGINE (Hands)
// ============================================
class MorphRegeneration {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.modes = ['exact', 'equivalent', 'morph_runtime', 'improved'];
  }

  generate({ contract, mode = 'equivalent', target = 'auto' }) {
    console.log(`[REGENERATION] Generating ${mode} version`);

    if (!this.validateContract(contract)) {
      throw new Error('Invalid contract for regeneration');
    }

    const architecture = this.selectArchitecture(contract.resonance);
    let generated;

    switch(mode) {
      case 'exact':
        generated = this.generateExact(contract);
        break;
      case 'equivalent':
        generated = this.generateEquivalent(contract, architecture);
        break;
      case 'morph_runtime':
        generated = this.generateMorphRuntime(contract, architecture);
        break;
      case 'improved':
        generated = this.generateImproved(contract, architecture);
        break;
      default:
        throw new Error(`Unknown regeneration mode: ${mode}`);
    }

    const verification = this.verifyGenerated(generated, contract);

    const result = {
      code: generated,
      mode,
      architecture,
      verification,
      contract,
      timestamp: Date.now()
    };

    console.log(`[REGENERATION] ✅ ${mode} version generated (${generated.length} chars)`);
    console.log(`[REGENERATION]    Architecture: ${architecture}`);
    console.log(`[REGENERATION]    Verification: ${verification.syntaxValid ? 'PASS' : 'FAIL'}`);

    return result;
  }

  validateContract(contract) {
    return contract && contract.intent && contract.capabilities;
  }

  selectArchitecture(resonance) {
    const circuit = resonance.circuitFamily;
    const map = MORPH_KERNEL_ENTRY.circuit_architecture_map;
    return map[circuit] || 'Auto-Select';
  }

  generateExact(contract) {
    const artifact = this.orchestrator.persistence.getArtifact(contract.artifactId);
    return artifact ? artifact.code : '';
  }

  generateEquivalent(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: false });
  }

  generateMorphRuntime(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, native: true });
  }

  generateImproved(contract, architecture) {
    return this.buildFromContract(contract, architecture, { optimize: true, improve: true, native: true });
  }

  buildFromContract(contract, architecture, options) {
    const builder = new CodeBuilder();
    const artifactId = contract.artifactId || contract.artifact_id;
    const original = artifactId ? this.orchestrator.persistence.getArtifact(artifactId) : null;

    if (!original) {
      // Fallback: generate from contract alone
      return this.generateFromContractOnly(contract, architecture, options);
    }

    // Add header
    builder.addComment(`Generated by Morph OS v1.0`);
    builder.addComment(`Mode: ${options.improve ? 'improved' : options.native ? 'morph_runtime' : 'equivalent'}`);
    builder.addComment(`Architecture: ${architecture}`);
    builder.addComment(`Original: ${original.metadata.name || 'unknown'}`);
    builder.addComment(`Gate: ${contract.resonance.primaryGate} | Circuit: ${contract.resonance.circuitFamily}`);
    builder.addComment('');

    // Add imports based on dependencies
    for (const dep of original.contract.dependencies) {
      builder.addImport(dep);
    }

    // Apply improvements
    let code = original.code;

    if (options.improve) {
      // Fix var → let/const (but let in for-loops)
      code = code.replace(/\bvar\b/g, 'const');
      // Fix const in for-loop initializer → let
      code = code.replace(/for\s*\(\s*const\s+/g, 'for(let ');

      // Fix loose equality
      code = code.replace(/([^=!])==([^=])/g, '$1===$2');
      code = code.replace(/\s==\s/g, ' === ');
      code = code.replace(/\s==\s/g, ' === ');

      // Remove debug logs
      code = code.replace(/console\.log\([^)]*\);?\s*\n/g, '\n');
      code = code.replace(/console\.log\([^)]*\);/g, '');
      code = code.replace(/console\.log\([^)]*\);/g, '');

      // Add error handling to async functions
      if (code.includes('async') && !code.includes('try')) {
        code = this.wrapWithErrorHandling(code);
      }

      // Add JSDoc comments
      code = this.addJSDocComments(code);
    }

    builder.addRaw(code);

    // Add exports
    for (const iface of original.contract.interfaces) {
      builder.addExport(iface);
    }

    return builder.build();
  }

  wrapWithErrorHandling(code) {
    // Simple wrapper - in production would be AST-based
    return code.replace(
      /async\s+function\s+(\w+)\s*\([^)]*\)\s*\{/g,
      'async function $1(...) { try {'
    ).replace(
      /\}\s*$/,
      '} catch (error) { console.error(`Error in $1:`, error); throw error; } }'
    );
  }

  addJSDocComments(code) {
    // Add JSDoc to functions
    return code.replace(
      /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g,
      (match, name, params) => {
        const paramDocs = params.split(',').filter(p => p.trim()).map(p => ` * @param {any} ${p.trim()}`).join('\n');
        return `/**\n * ${name}\n${paramDocs}\n * @returns {any}\n */\n${match}`;
      }
    );
  }

  generateFromContractOnly(contract, architecture, options) {
    const builder = new CodeBuilder();

    builder.addComment(`Generated by Morph OS v1.0`);
    builder.addComment(`Mode: ${options.improve ? 'improved' : options.native ? 'morph_runtime' : 'equivalent'}`);
    builder.addComment(`Architecture: ${architecture}`);
    builder.addComment(`Gate: ${contract.resonance.primaryGate} | Circuit: ${contract.resonance.circuitFamily}`);
    builder.addComment('');

    // Generate structure from intent
    const intent = contract.intent.primary || 'general';
    if (intent.includes('object_oriented')) {
      builder.addStructure(intent);
    }

    // Add methods from capabilities
    for (const [capability, enabled] of Object.entries(contract.capabilities)) {
      if (enabled) {
        builder.addMethod(capability);
