class MorphMemory {
  constructor() {
    this.layers = {
      active: new Map(),
      lineage: new Map(),
      transit: new Map(),
      experience: new Map()
    };
  }

  store(layer, key, value) {
    this.layers[layer].set(key, value);
  }

  retrieve(layer, key) {
