  }

  formChannel(channelName, channelData) {
    this.activeChannels.add(channelName);
    this.architectureInstances.set(channelName, {
      type: channelData.architecture,
      data: channelData,
      state: 'stable'
    });
  }

  // Classify code into circuit family based on characteristics
  classifyCode(contract) {
    const intents = (contract.intent || '').split(', ');
