      } else {
        safeTransforms.push('var_to_let');
      }
    }

    // Unsafe: adding JSDoc to complex functions
    if (analysis.structure.cyclomaticComplexity > 10) {
      unsafeTransforms.push('add_jsdoc_complex');
    } else {
      safeTransforms.push('add_jsdoc');
    }

    // Unsafe: restructuring large files
    if (analysis.structure.linesOfCode > 200) {
      unsafeTransforms.push('restructure_large_file');
    }

    // Determine recommended mode
    let recommendedMode = 'equivalent';
    let confidence = 0.5;

    if (riskScore < 0.3 && safeTransforms.length >= 3) {
      recommendedMode = 'improved';
      confidence = 0.85;
    } else if (riskScore < 0.6 && safeTransforms.length >= 2) {
      recommendedMode = 'improved';
      confidence = 0.70;
    } else if (riskScore < 0.8 && safeTransforms.length >= 1) {
      recommendedMode = 'equivalent';
      confidence = 0.60;
    } else {
      recommendedMode = 'exact';
      confidence = 0.40;
    }

