      classes: (code.match(/\bclass\b/g) || []).length,
      branches: (code.match(/\b(if|else|switch|case|for|while)\b/g) || []).length,
      cyclomatic: ((code.match(/\b(if|else|switch|case|for|while)\b/g) || []).length) + 1
