  }

  generateReasoning(riskScore, safe, unsafe, analysis) {
    const reasons = [];

    if (riskScore < 0.3) {
      reasons.push('Low complexity and few dependencies make this safe to improve aggressively.');
    } else if (riskScore < 0.6) {
