    }

    if (unsafe.length > 0) {
      reasons.push(`Unsafe transforms requiring manual review: ${unsafe.join(', ')}.`);
    }

    if (analysis.structure.cyclomaticComplexity > 20) {
      reasons.push('High cyclomatic complexity suggests the code may have hidden control flow dependencies.');
    }

    return reasons;
  }
}

