    let recommendedMode = 'equivalent';
    let confidence = 0.5;

    if (riskScore < 0.3 && safeTransforms.length >= 3) {
      recommendedMode = 'improved';
      confidence = 0.85;
    } else if (riskScore < 0.6 && safeTransforms.length >= 2) {
      recommendedMode = 'improved';
      confidence = 0.70;
    } else if (riskScore < 0.8 && safeTransforms.length >= 1) {
      recommendedMode = 'equivalent';
      confidence = 0.60;
    } else {
      recommendedMode = 'exact';
      confidence = 0.40;
    }

    const plan = {
      artifactId,
      risk: this.riskLabel(riskScore),
      riskScore,
      recommendedMode,
      safeTransforms,
      unsafeTransforms,
      confidence,
      analysis: {
        complexity: analysis.structure.cyclomaticComplexity,
        lines: analysis.structure.linesOfCode,
        issues: analysis.issues.length,
        patterns: analysis.patterns
      },
      reasoning: this.generateReasoning(riskScore, safeTransforms, unsafeTransforms, analysis),
      timestamp: Date.now()
    };

    console.log(`[STRATEGY] ✅ Plan: ${plan.risk} risk, ${recommendedMode} mode, ${confidence.toFixed(2)} confidence`);
    console.log(`[STRATEGY]    Safe: ${safeTransforms.join(', ') || 'none'}`);
    console.log(`[STRATEGY]    Unsafe: ${unsafeTransforms.join(', ') || 'none'}`);

    return plan;
